<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientSectorIdentifierUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientSectorIdentifierUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withSectorIdentifierUri,
 * getSectorIdentifierUri/sectorIdentifierUri accessors, and isSectorIdentifierUriChanged with/without original.
 */
class TrustedClientSectorIdentifierUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSectorIdentifierUri creates a new instance with the SectorIdentifierUri set
     * from a string value, and getSectorIdentifierUri returns the primitive string.
     */
    public function testWithSectorIdentifierUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSectorIdentifierUriAccessorUnitTest();

        // Act
        $result = $holder->withSectorIdentifierUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSectorIdentifierUri());
    }
    /**
     * Asserts that withsectorIdentifierUri has access to the value object
     * from a string value, and getSectorIdentifierUri returns the primitive string.
     */
    public function testWithSectorIdentifierUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSectorIdentifierUriAccessorUnitTest();

        // Act
        $result = $holder->withSectorIdentifierUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->sectorIdentifierUri()->value());
    }
    public function testChangedSectorIdentifierUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSectorIdentifierUriAccessorUnitTest();
        $original = $holder->withSectorIdentifierUri('one');
        $same = $holder->withSectorIdentifierUri('one');
        $modified = $holder->withSectorIdentifierUri('other');

        // Act
        $unchanged = $holder->isSectorIdentifierUriChanged();
        $withSame = $original->isSectorIdentifierUriChanged($same);
        $withDiferent = $original->isSectorIdentifierUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientSectorIdentifierUriAccessorUnitTest
{
    use TrustedClientSectorIdentifierUriAccessor;
}
